    "code": "```java\nvoid testArrayTypes()  {\n    final ArrayBuilder ab = new ArrayBuilder(1);\n    // An engine for expressions with args final JexlFeatures features = JexlFeatures.createScript().script(false);\n    final JexlEngine jexl = new JexlBuilder() .features(features) .create();\n    // Super for ClassC final Set<Class<?>> superSet = ClassMisc.getSuperClasses(ClassC.class);\n    assertTrue(superSet.size() > 0);\n    // verify the order final List<Class<?>> ordered = Arrays.asList( ClassB.class, ClassA.class, Class0.class, InterC.class, InterX.class, InterB.class, InterA.class, Inter0.class);\n    int i = 0;\n    for(final Class<?> clazz : superSet)\n    {\n        assertEquals(clazz, ordered.get(i++), \"order \" + i);\n    }\n    // intersect ClassC, ClassX -> Class0 Class<?> inter = ClassMisc.getCommonSuperClass(ClassC.class, ClassX.class);\n    assertEquals(Class0.class, inter);\n    // intersect ClassC, ClassB -> ClassB inter = ClassMisc.getCommonSuperClass(ClassC.class, ClassB.class);\n    assertEquals(ClassB.class, inter);\n    // intersect ArrayList, ArrayDeque -> AbstractCollection final Class<?> list = ClassMisc.getCommonSuperClass(ArrayList.class, ArrayDeque.class);\n    assertEquals(list, AbstractCollection.class);\n    final Set<Class<?>> sset = ClassMisc.getSuperClasses(ArrayList.class, ArrayDeque.class);\n    assertFalse(sset.isEmpty());\n    // in java 21, a SequenceCollection interface is added to the sset final List<Class<?>> expected = Arrays.asList(AbstractCollection.class, Collection.class, Iterable.class, Cloneable.class, Serializable.class);\n    assertTrue(sset.containsAll(expected));\n    Class<?> collection = ClassMisc.getCommonSuperClass(ArrayList.class, Collections.emptyList().getClass());\n    assertEquals(AbstractList.class, collection);\n    collection = ClassMisc.getSuperClasses(ArrayList.class, Collections.emptyList().getClass()) .stream().findFirst().orElse(Object.class);\n    // apply on objects final Object a = new ClassA(1);\n    final Object b = new ClassB(2);\n    final Object c = new ClassC(3);\n    final Object x = new ClassX(4);\n    JexlScript script;\n    Object result;\n    script = jexl.createScript(\"[ a, b, c, d ]\", \"a\", \"b\", \"c\", \"d\");\n    // intersect a, b, c, c -> classA result = script.execute(null, a, b, c, c);\n    assertTrue(result.getClass().isArray() && result.getClass().getComponentType().equals(ClassA.class));\n    // intersect a, b, c, x -> class0 result = script.execute(null, a, b, c, x);\n    assertTrue(result.getClass().isArray() && result.getClass().getComponentType().equals(Class0.class));\n    // intersect x, c, b, a -> class0 result = script.execute(null, x, c, b, a);\n    assertTrue(result.getClass().isArray() & result.getClass().getComponentType().equals(Class0.class));\n    // intersect a, b, c, d -> inter0 final Object d = new ClassD();\n    result = script.execute(null, a, b, c, d);\n    assertTrue(result.getClass().isArray() && result.getClass().getComponentType().equals(Inter0.class));\n    script = jexl.createScript(\"[ a, b, c, d, ... ]\", \"a\", \"b\", \"c\", \"d\");\n    // intersect a, b, c, c -> classA result = script.execute(null, a, b, c, c);\n    assertInstanceOf(List.class, result);\n}\n```"
