    if (ii.hasNext())
    {
        long l = ii.next();
        assertEquals(first, l);
        while(ii.hasNext())
        {
            l = ii.next();
        }
        assertEquals(last, l);
    }
    else
    {
        fail("empty iterator?");
    }
}
