        }
    }
    // No container exists for that message Id. Create one and insert it into the hash table. if (container == null)
    {
        container = new NntpThreadContainer();
        container.threadable = threadable;
        idTable.put(id, container);
    }
    // Iterate through all the references and create ThreadContainers for any references that // don't have them. NntpThreadContainer parentRef = null;
    {
        final String[] references = threadable.messageThreadReferences();
        for (final String refString : references)
        {
            NntpThreadContainer ref = idTable.get(refString);
            // if this id doesn't have a container, create one if (ref == null)
            {
                ref = new NntpThreadContainer();
                idTable.put(refString, ref);
            }
            // Link references together in the order they appear in the References: header, // IF they don't have a parent already && // IF it will not cause a circular reference if (parentRef != null && ref.parent == null && parentRef != ref && !ref.findChild(parentRef))
            {
                // Link ref into the parent's child list ref.parent = parentRef;
                ref.next = parentRef.child;
                parentRef.child = ref;
            }
            parentRef = ref;
        }
