static String quoteMailboxName(final String input)  {
    if (input == null)
    {
        // Don't throw NPE here return null;
    }
    if (input.isEmpty())
    {
        return "\"\"";
        // return the string ""
    }
    // Length check is necessary to ensure a lone double-quote is quoted if (input.length() > 1 && input.startsWith("\"") && input.endsWith("\""))
    {
        return input;
        // Assume already quoted
    }
    if (input.contains(" "))
    {
        // quoted strings must escape \ and " return "\"" + input.replaceAll("([\\\\\"])", "\\\\$1") + "\"";
    }
    return input;
}
