        Calendar parsed = parser.parseTimestamp(fmtTime);
        // the timestamp is ahead of now (by one hour), but // that's within range of the "slop" factor. // so the date is still considered this year. assertEquals(0, cal.get(Calendar.YEAR) - parsed.get(Calendar.YEAR), "test.slop.no.roll.back.year");
