private static int getEntry(final SimpleDateFormat dateFormat)  {
    if (dateFormat == null)
    {
        return 0;
    }
    final String FORMAT_CHARS = "SsmHdM";
    final String pattern = dateFormat.toPattern();
    for (final char ch : FORMAT_CHARS.toCharArray())
    {
        if (pattern.indexOf(ch) != -1)
        {
            // found the character switch (ch)
            {
                case 'S': return indexOf(Calendar.MILLISECOND);
                case 's': return indexOf(Calendar.SECOND);
                case 'm': return indexOf(Calendar.MINUTE);
                case 'H': return indexOf(Calendar.HOUR_OF_DAY);
                case 'd': return indexOf(Calendar.DAY_OF_MONTH);
                case 'M': return indexOf(Calendar.MONTH);
            }
        }
    }
    return 0;
}
