public void testPOP3ClientStateTransition() throws Exception  {
    final POP3Client pop = new POP3Client();
    // Initial state assertEquals(110, pop.getDefaultPort());
    assertEquals(POP3.DISCONNECTED_STATE, pop.getState());
    assertNull(pop.reader);
    assertNotNull(pop.replyLines);
    // Now connect pop.connect(mailhost);
    assertEquals(POP3.AUTHORIZATION_STATE, pop.getState());
    // Now authenticate pop.login(user, password);
    assertEquals(POP3.TRANSACTION_STATE, pop.getState());
    // Now do a series of commands and make sure the state stays as it should pop.noop();
    assertEquals(POP3.TRANSACTION_STATE, pop.getState());
    pop.status();
    assertEquals(POP3.TRANSACTION_STATE, pop.getState());
    // Make sure we have at least one message to test final POP3MessageInfo[] msg = pop.listMessages();
    if (msg.length > 0)
