            "code": "```java\nprotected Socket _openDataConnection_(final String command, final String arg) throws IOException  {\n    if (dataConnectionMode != ACTIVE_LOCAL_DATA_CONNECTION_MODE && dataConnectionMode != PASSIVE_LOCAL_DATA_CONNECTION_MODE)\n    {\n        return null;\n    }\n    final boolean isInet6Address = getRemoteAddress() instanceof Inet6Address;\n    final Socket socket;\n    final int soTimeoutMillis = DurationUtils.toMillisInt(dataTimeout);\n    if (dataConnectionMode == ACTIVE_LOCAL_DATA_CONNECTION_MODE)\n    {\n        // if no activePortRange was set (correctly) -> getActivePort() = 0 // -> new ServerSocket(0) -> bind to any free local port try (ServerSocket server = _serverSocketFactory_.createServerSocket(getActivePort(), 1, getHostAddress()))\n        {\n            // Try EPRT only if remote server is over IPv6, if not use PORT, // because EPRT has no advantage over PORT on IPv4. // It could even have the disadvantage, // that EPRT will make the data connection fail, because // today's intelligent NAT Firewalls are able to // substitute IP addresses in the PORT command, // but might not be able to recognize the EPRT command. if (isInet6Address)\n            {\n                if (!FTPReply.isPositiveCompletion(eprt(getReportHostAddress(), server.getLocalPort())))\n                {\n                    return null;\n                }\n            }\n            else if (!FTPReply.isPositiveCompletion(port(getReportHostAddress(), server.getLocalPort())))\n            {\n                return null;\n            }\n            if (restartOffset > 0 && !restart(restartOffset))\n            {\n                return null;\n            }\n            if (!FTPReply.isPositivePreliminary(sendCommand(command, arg)))\n            {\n                return null;\n            }\n            // For now, let's just use the data timeout value for waiting for // the data connection. It may be desirable to let this be a // separately configurable value. In any case, we really want // to allow preventing the accept from blocking indefinitely. if (soTimeoutMillis >= 0)\n            {\n                server.setSoTimeout(soTimeoutMillis);\n            }\n            socket = wrapOnDeflate(server.accept());\n            // Ensure the timeout is set before any commands are issued on the new socket if (soTimeoutMillis >= 0)\n            {\n                socket.setSoTimeout(soTimeoutMillis);\n            }\n            if (receiveDataSocketBufferSize > 0)\n            {\n                socket.setReceiveBufferSize(receiveDataSocketBufferSize);\n            }\n            if (sendDataSocketBufferSize > 0)\n            {\n                socket.setSendBufferSize(sendDataSocketBufferSize);\n            }\n        }\n    }\n    else\n    {\n        // We must be in PASSIVE_LOCAL_DATA_CONNECTION_MODE // Try EPSV command first on IPv6 - and IPv4 if enabled. // When using IPv4 with NAT it has the advantage // to work with more rare configurations. // E.g. if FTP server has a static PASV address (external network) // and the client is coming from another internal network. // In that case the data connection after PASV command would fail, // while EPSV would make the client succeed by taking just the port. final boolean attemptEPSV = isUseEPSVwithIPv4() || isInet6Address;\n        if (attemptEPSV && epsv() == FTPReply.ENTERING_EPSV_MODE)\n        {\n            _parseExtendedPassiveModeReply(_replyLines.get(0));\n        }\n        else\n        {\n            if (isInet6Address)\n            {\n                return null;\n                // Must use EPSV for IPV6\n            }\n            // If EPSV failed on IPV4, revert to PASV if (pasv() != FTPReply.ENTERING_PASSIVE_MODE)\n            {\n                return null;\n            }\n            _parsePassiveModeReply(_replyLines.get(0));\n        }\n        socket = wrapOnDeflate(_socketFactory_.createSocket());\n        if (receiveDataSocketBufferSize > 0)\n        {\n            socket.setReceiveBufferSize(receiveDataSocketBufferSize);\n        }\n        if (sendDataSocketBufferSize > 0)\n        {\n            socket.setSendBufferSize(sendDataSocketBufferSize);\n        }\n        if (passiveLocalHost != null)\n        {\n            socket.bind(new InetSocketAddress(passiveLocalHost, 0));\n        }\n        // For now, let's just use the data timeout value for waiting for // the data connection. It may be desirable to let this be a // separately configurable value. In any case, we really want // to allow preventing the accept from blocking indefinitely. if (soTimeoutMillis >= 0)\n        {\n            socket.setSoTimeout(soTimeoutMillis);\n        }\n        socket.connect(new InetSocketAddress(passiveHost, passivePort), connectTimeout);\n        if (restartOffset > 0 && !restart(restartOffset))\n        {\n            socket.close();\n            return null;\n        }\n        if (!FTPReply.isPositivePreliminary(sendCommand(command, arg)))\n        {\n            socket.close();\n            return null;\n        }\n    }\n    if (remoteVerificationEnabled && !verifyRemote(socket))\n    {\n        // Grab the host before we close the socket to avoid NET-663 final String socketHostAddress = getHostAddress(socket);\n        final String remoteHostAddress = getHostAddress(_socket_);\n        IOUtils.closeQuietly(socket);\n        throw new IOException(\"Host attempting data connection \" + socketHostAddress + \" is not same as server \" + remoteHostAddress);\n    }\n    return socket;\n}\n```"
